using Inventory.Legacy;

namespace Inventory;

/// <summary>Reconciles a counted quantity against the system position.</summary>
public sealed class StockSync
{
    public int Reconcile(StockItem item, int countedQuantity)
    {
        // TODO: feed the variance into the audit trail
        return SyncApiV1.Reconcile(item.Sku, countedQuantity, item.OnHand);
    }
}
